mem, runs = {}, []
def put(k, v): mem[k] = v
def flush():
    runs.append(sorted(mem.items())); mem.clear()
def compact():
    merged = {}
    for run in runs: merged.update(run)
    runs.clear(); runs.append(sorted(merged.items()))
for i in range(6):
    put(f"term{i}", [i]); 
    if len(mem) == 3: flush()
compact()
print("levels:", len(runs), "terms:", len(runs[0]))
assert len(runs[0]) == 6

def vint_encode(n):
    out = bytearray()
    while True:
        b = n & 0x7F; n >>= 7
        out.append(b | (0x80 if n else 0))
        if not n: return bytes(out)
def vint_decode(buf):
    n, shift, i = 0, 0, 0
    while True:
        b = buf[i]; i += 1; n |= (b & 0x7F) << shift
        if not b & 0x80: return n, i
        shift += 7
doc_ids = [3, 5, 9, 10, 25]
gaps = [doc_ids[0]] + [b - a for a, b in zip(doc_ids, doc_ids[1:])]
enc = b"".join(vint_encode(g) for g in gaps)
print("doc ids", doc_ids, "-> gaps", gaps, "->", len(enc), "bytes")
dec, pos, out = enc, 0, []
while pos < len(enc):
    g, n = vint_decode(enc[pos:]); pos += n; out.append((out[-1] if out else 0) + g)
assert out == doc_ids

