trie = {}
def add(word):
    node = trie
    for ch in word: node = node.setdefault(ch, {})
    node["$"] = True
def prefixed(p):
    node = trie
    for ch in p: node = node.get(ch, {})
    out = []
    def walk(n, s):
        if "$" in n: out.append(s)
        for ch, c in n.items():
            if ch != "$": walk(c, s + ch)
    walk(node, p); return out
for w in ["archive", "arch", "arctic", "art"]: add(w)
print("prefix 'arc':", prefixed("arc"))
assert prefixed("arc") == ["arch", "archive", "arctic"]
